        "",
        "",
        "",
        "",
    )
    private val pixels: ByteArray by lazy { decode() }

    fun readBit(code: Int, x: Int, y: Int): Boolean {
        val idx = if (code in 0xac00..0xd7a3) code - 0xac00
            else extraCodes.binarySearch(code).let { if (it >= 0) 11172 + it else 11172 + extraCodes.binarySearch(0x25a1).let { i -> if (i >= 0) i else 0 } }
        val offset = idx * stride + y * (width / 8) + (x / 8)
        if (offset !in pixels.indices) return false
        return ((pixels[offset].toInt() and 0xff) and (0x80 ushr (x % 8))) != 0
    }

    /** This custom base64 and zero-run decoder avoids java.util.zip and Android Base64 APIs. */
    private fun decode(): ByteArray {
        val expected = (11172 + extraCodes.size) * stride
        val out = ByteArray(expected)
        var dest = 0
        var zeroPending = false
        var carry = 0
        var bits = 0
        for (chunk in blocks) for (ch in chunk) {
            val digit = when(ch) {
                in 'A'..'Z' -> ch.code - 65
                in 'a'..'z' -> ch.code - 71
                in '0'..'9' -> ch.code + 4
                '+' -> 62
                '/' -> 63
                else -> -1
            }
            if (digit == -1) continue
            carry = (carry shl 6) or digit
            bits += 6
            if (bits >= 8) {
                bits -= 8
                val b = (carry ushr bits) and 255
                carry = carry and ((1 shl bits) - 1)
                if (zeroPending) {
                    dest += b
                    zeroPending = false
                } else if (b == 0) zeroPending = true
                else if (dest < expected) out[dest++] = b.toByte()
            }
        }
        check(dest == expected) { "Glyph data is incomplete: $dest / $expected" }
        return out
    }
}
